<?php
require __DIR__.'/app/bootstrap.php';$user=require_permission('view_staff');$error='';
try{[$where,$params,$filters]=staff_filter($_GET);}catch(InvalidArgumentException $e){$error=$e->getMessage();[$where,$params,$filters]=staff_filter([]);}
$total=(int)query('SELECT COUNT(*) FROM staff_directory s'.$where,$params)->fetchColumn();$page=page_number($total);$offset=($page-1)*25;
$rows=query('SELECT s.*,d.name department_name,u.full_name tl_name,EXISTS(SELECT 1 FROM staff_photos p WHERE p.staff_id=s.id) has_photo FROM staff_directory s LEFT JOIN departments d ON d.id=s.department_id LEFT JOIN users u ON u.id=s.tl_id'.$where.' ORDER BY s.full_name,s.id LIMIT 25 OFFSET '.$offset,$params)->fetchAll();
page_start('Staff directory',$user);?><div class="section-head"><div><h2>The people behind the work</h2><p class="muted">Profiles, assignments and the history of every employee.</p></div><div class="actions"><?php if(user_can('export_staff')):?><a class="button button-secondary" href="export.php?<?=e(http_build_query(array_merge($filters,['type'=>'staff'])))?>">Export CSV</a><?php endif;if(user_can('manage_staff')):?><a class="button" href="employee-form.php">+ Add employee</a><?php endif;?></div></div><?php error_notice($error);?>
<section class="panel"><form class="filter-grid" method="get"><input type="hidden" name="status" value="<?=e($filters['status'])?>"><label>Search<input name="q" placeholder="Name, code or position" value="<?=e($filters['q'])?>"></label><label>Department<select name="department_id"><option value="">All departments</option><?php options(active_departments(),$filters['department_id']);?></select></label><label>Team leader<select name="tl_id"><option value="">All team leaders</option><?php options(query("SELECT u.id,u.full_name FROM users u JOIN roles r ON r.id=u.role_id WHERE r.slug='team-leader' ORDER BY u.full_name")->fetchAll(),$filters['tl_id'],'full_name');?></select></label><label>Team<select name="team"><option value="">All teams</option><?php foreach(query('SELECT DISTINCT team_label FROM staff_directory ORDER BY team_label') as $team):?><option <?=$filters['team']===$team['team_label']?'selected':''?> value="<?=e($team['team_label'])?>"><?=e($team['team_label'])?></option><?php endforeach;?></select></label><label>Started from<input type="date" name="from" value="<?=e($filters['from'])?>"></label><label>Started to<input type="date" name="to" value="<?=e($filters['to'])?>"></label><div class="actions"><button class="button">Apply</button><a href="staff.php" class="button button-secondary">Reset</a></div></form></section>
<section class="panel flush"><nav class="tabs" aria-label="Staff status"><?php foreach([''=>'All staff']+STAFF_STATUSES as $key=>$label):?><a class="<?=$filters['status']===$key?'selected':''?>" href="?<?=e(http_build_query(array_merge($filters,['status'=>$key])))?>"><?=e($label)?></a><?php endforeach;?></nav><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Position / shift</th><th>Department / team</th><th>Team leader</th><th>Started</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><div class="person-cell"><?php employee_avatar($row);?><span><a href="employee.php?id=<?=$row['id']?>"><?=e($row['full_name'])?></a><small><?=e($row['employee_code'])?></small></span></div></td><td><?=e($row['position'])?><span class="cell-secondary"><?=e($row['shift_schedule'])?></span></td><td><?=e($row['department_name'])?><span class="cell-secondary"><?=e($row['team_label'])?></span></td><td><?=e($row['tl_name'])?></td><td><?=e($row['start_date'])?><?php if($row['exit_date']):?><span class="cell-secondary">Exited <?=e($row['exit_date'])?></span><?php endif;?></td><td><span class="badge <?=e($row['employment_status'])?>"><?=e(STAFF_STATUSES[$row['employment_status']])?></span></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="empty">No employees match these filters.</td></tr><?php endif;?></tbody></table></div><?php pagination($total,$page);?></section><?php page_end();
